insert into public.fce_stations(program_id,code,version,title,core,candidate_instructions,examiner_package,source_url)
select id,'FCE-01','1.0.0','Exertional dyspnea with a diastolic murmur',true,'In 8 minutes, take a focused History and perform a focused Physical Examination relevant to your working hypotheses. Explain what you are doing and respect consent. At the bell, move to the 4-minute post-encounter form: Problem Representation, ranked Differential Diagnosis and evidence justification.','{"domains":{"H1":"Clarifies tempo/functional limitation and key associated symptoms (dyspnea trajectory, palpitations, chest pain, syncope, orthopnoea/PND).","H2":"Seeks relevant context/alternatives (known murmur/valve disease, hypertension, infection/endocarditis context, rheumatic history where locally relevant).","PE1":"Pulse + blood pressure: rate/rhythm and pulse character; obtains or meaningfully interprets BP.","PE2":"JVP assessment with appropriate positioning and identification of venous pulse.","PE3":"Precordial inspection/palpation including apex/PMI location and character.","PE4":"Systematic cardiac auscultation with attention to a diastolic murmur and appropriate positioning (sitting forward/end-expiration when indicated).","PE5":"Congestion screen: lung bases and peripheral edema, linked to severity/complication rather than performed mechanically.","PR":"Problem Representation","DDx":"Ranked Differential Diagnosis","JUST":"Evidence justification"},"source_text":"CORE STATION  CVS. 12 minutes total: 8-minute observed encounter + 4-minute post-encounter reasoning.\nPrompt / domain\nSP response\nOpening statement\n“I get short of breath when I walk fast, and sometimes my heartbeat feels very strong.”\nOnset / course\nGradual over about 6 months; clearly worse over the last 2 months.\nExercise tolerance\nPreviously could climb 3 flights; now stops after 1–2.\nChest pain / syncope\nNo exertional chest pain; no fainting.\nPalpitations\nAwareness of forceful heartbeat, especially when lying down; no sustained racing episodes.\nOrthopnoea / PND / edema\nNo PND; uses one pillow; no ankle swelling.\nFever / infection\nNo current fever. No recent prolonged febrile illness.\nPast history\nHypertension for several years; no known previous valve intervention.\nMedications\nAmlodipine only; no stimulant use.\nSmoking / family\nDoes not smoke; no known early sudden cardiac death.\nManoeuvre / domain\nStandardized finding to provide\nPulse + BP\nPulse 84/min regular and bounding. BP 158/54 mmHg.\nJVP\nJVP not elevated.\nApex / PMI\nApex is displaced laterally and feels hyperdynamic.\nAuscultation\nEarly diastolic decrescendo murmur, loudest along the left sternal border; more apparent sitting forward in end-expiration. No systolic ejection murmur.\nLung bases / edema\nLungs clear; no peripheral pitting edema.\nCode\nDomain\nScore\nH1\nClarifies tempo/functional limitation and key associated symptoms (dyspnea trajectory, palpitations, chest pain, syncope, orthopnoea/PND).\n0–2\nH2\nSeeks relevant context/alternatives (known murmur/valve disease, hypertension, infection/endocarditis context, rheumatic history where locally relevant).\n0–2\nPE1\nPulse + blood pressure: rate/rhythm and pulse character; obtains or meaningfully interprets BP.\n0–2\nPE2\nJVP assessment with appropriate positioning and identification of venous pulse.\n0–2\nPE3\nPrecordial inspection/palpation including apex/PMI location and character.\n0–2\nPE4\nSystematic cardiac auscultation with attention to a diastolic murmur and appropriate positioning (sitting forward/end-expiration when indicated).\n0–2\nPE5\nCongestion screen: lung bases and peripheral edema, linked to severity/complication rather than performed mechanically.\n0–2\nPR\nProblem Representation\n0–2\nDDx\nRanked Differential Diagnosis\n0–2\nJUST\nEvidence justification\n0–2\nDomain\n0\n1\n2\nProblem Representation\nDiagnosis only or copied facts\nSome synthesis but misses tempo/major discriminators\nConcise transformed representation: middle-aged adult with progressive exertional dyspnea/forceful pulsation, wide pulse pressure/bounding pulse, hyperdynamic displaced apex and early diastolic murmur without overt congestion.\nRanked Differential\nNo plausible leading hypothesis\nAortic regurgitation plausible but alternatives weak/unranked\nChronic aortic regurgitation leading; coherent alternatives such as other valvular disease/high-output state; ranking reflects murmur + pulse findings.\nEvidence justification\nUnsupported label\nUses one supporting clue only\nIntegrates ≥2 discriminating findings (diastolic murmur, wide pulse pressure/bounding pulse, hyperdynamic displaced apex) and may use clear lungs/JVP as absence of overt congestion.\nCritical safety / professionalism flags  Stop or mark a safety/professionalism flag for painful/unsafe examination, repeated forceful palpation after SP discomfort, refusal to respect consent, or fabrication of a finding not elicited/provided.\n","anchor":"0 = omitted/unsafe/irrelevant; 1 = partially competent or poorly targeted; 2 = competent, targeted, and interpretable for this learner level.","global":"1 Unsafe/non-coherent; 2 Weak; 3 Developing; 4 Competent; 5 Strong. Report separately; never add to /20."}'::jsonb,'https://drive.google.com/file/d/1rPUKlJQ_cajr2av5r0IODik4zqOKeAXd/view' from public.programs where code='SEIP26' on conflict do nothing;
insert into public.fce_stations(program_id,code,version,title,core,candidate_instructions,examiner_package,source_url)
select id,'FCE-02','1.0.0','Progressive abdominal distension with peripheral edema',true,'In 8 minutes, take a focused History and perform a focused Physical Examination relevant to your working hypotheses. Explain what you are doing and respect consent. At the bell, move to the 4-minute post-encounter form: Problem Representation, ranked Differential Diagnosis and evidence justification.','{"domains":{"H1":"Clarifies tempo of abdominal distension/edema and symptoms of decompensation (dyspnea, confusion, bleeding, fever/abdominal pain).","H2":"Seeks etiologic/alternative context (alcohol, viral hepatitis risk/history, medicines; cardiac/renal symptoms).","PE1":"General inspection and mental status, including scleral icterus when looked for.","PE2":"JVP assessment to help distinguish hepatic from cardiac fluid retention.","PE3":"Peripheral edema assessment with safe pitting technique.","PE4":"Focused abdominal inspection/palpation including liver edge/tenderness and gross distension.","PE5":"Performs a valid ascites manoeuvre — preferably shifting dullness; fluid wave is optional adjunct rather than mandatory.","PR":"Problem Representation","DDx":"Ranked Differential Diagnosis","JUST":"Evidence justification"},"source_text":"CORE STATION  Liver. 12 minutes total: 8-minute observed encounter + 4-minute post-encounter reasoning.\nPrompt / domain\nSP response\nOpening statement\n“My abdomen has been getting bigger and my ankles swell by the evening.”\nOnset / course\nProgressive over 3 months.\nAbdominal pain / fever\nNo severe pain; no fever.\nBreathlessness\nMild discomfort when very full, but no orthopnoea or PND.\nBleeding\nNo hematemesis or melena.\nConfusion / sleep reversal\nNo confusion; family has not noticed personality change.\nAlcohol\nLong-standing alcohol intake above recommended limits; exact amount if asked: ~4–5 drinks most days for many years.\nHepatitis / transfusion\nNo known viral hepatitis; no prior diagnosis of chronic liver disease.\nRenal / urinary\nNo frothy urine; urine output feels unchanged.\nMedications\nOccasional NSAID use; no diuretics.\nManoeuvre / domain\nStandardized finding to provide\nGeneral / eyes\nMild scleral icterus; alert and oriented.\nJVP\nJVP not elevated.\nPeripheral edema\nBilateral pitting edema to lower shins.\nAbdominal inspection/palpation\nDistended abdomen with flank fullness; no focal peritonism; liver edge firm but not acutely tender.\nAscites manoeuvre\nShifting dullness is present. Fluid wave may be reported as present if correctly attempted.\nCode\nDomain\nScore\nH1\nClarifies tempo of abdominal distension/edema and symptoms of decompensation (dyspnea, confusion, bleeding, fever/abdominal pain).\n0–2\nH2\nSeeks etiologic/alternative context (alcohol, viral hepatitis risk/history, medicines; cardiac/renal symptoms).\n0–2\nPE1\nGeneral inspection and mental status, including scleral icterus when looked for.\n0–2\nPE2\nJVP assessment to help distinguish hepatic from cardiac fluid retention.\n0–2\nPE3\nPeripheral edema assessment with safe pitting technique.\n0–2\nPE4\nFocused abdominal inspection/palpation including liver edge/tenderness and gross distension.\n0–2\nPE5\nPerforms a valid ascites manoeuvre — preferably shifting dullness; fluid wave is optional adjunct rather than mandatory.\n0–2\nPR\nProblem Representation\n0–2\nDDx\nRanked Differential Diagnosis\n0–2\nJUST\nEvidence justification\n0–2\nDomain\n0\n1\n2\nProblem Representation\nDiagnosis only or copied details\nCaptures fluid retention but weak transformation\nAdult with subacute progressive abdominal distension and bilateral edema, mild jaundice, ascites on shifting dullness and normal JVP, without encephalopathy/peritonism.\nRanked Differential\nNo plausible leading hypothesis\nCirrhosis/portal-hypertensive ascites plausible but alternatives weak\nDecompensated chronic liver disease/cirrhosis leading; cardiac and renal causes explicitly considered and ranked using JVP/urinary context; other causes of ascites acceptable if coherent.\nEvidence justification\nUnsupported conclusion\nOne positive feature only\nUses ascites + edema + jaundice/chronic liver context and a normal JVP/absence of orthopnoea as discriminating evidence against a primary cardiac explanation.\nCritical safety / professionalism flags  Immediate examiner note for unsafe deep palpation, repeated painful manoeuvres despite SP request to stop, failure to respect consent, or ignoring overt confusion/hemodynamic instability if introduced during a variant dry run.\n","anchor":"0 = omitted/unsafe/irrelevant; 1 = partially competent or poorly targeted; 2 = competent, targeted, and interpretable for this learner level.","global":"1 Unsafe/non-coherent; 2 Weak; 3 Developing; 4 Competent; 5 Strong. Report separately; never add to /20."}'::jsonb,'https://drive.google.com/file/d/1rPUKlJQ_cajr2av5r0IODik4zqOKeAXd/view' from public.programs where code='SEIP26' on conflict do nothing;
insert into public.fce_stations(program_id,code,version,title,core,candidate_instructions,examiner_package,source_url)
select id,'FCE-R1','1.0.0','Chronic dyspnea with obstructive-airflow phenotype',false,'In 8 minutes, take a focused History and perform a focused Physical Examination relevant to your working hypotheses. Explain what you are doing and respect consent. At the bell, move to the 4-minute post-encounter form: Problem Representation, ranked Differential Diagnosis and evidence justification.','{"domains":{"H1":"Characterises chronic dyspnea/cough/sputum and exacerbation pattern.","H2":"Assesses smoking/exposure history and considers asthma/cardiac/infective alternatives.","PE1":"Vitals + RR/SpO₂/work of breathing.","PE2":"Chest expansion/symmetry.","PE3":"Comparative percussion.","PE4":"Auscultation of air entry and added sounds.","PE5":"Focused cardiovascular/edema screen when needed for alternatives.","PR":"Problem Representation","DDx":"Ranked Differential Diagnosis","JUST":"Evidence justification"},"source_text":"RESERVE / PARALLEL CANDIDATE — NOT EQUIVALENCE-LOCKED  Respiratory. 12 minutes total: 8-minute observed encounter + 4-minute post-encounter reasoning.\nPrompt / domain\nSP response\nOpening\n“I get out of breath walking and I cough most mornings.”\nCourse\nSeveral years, slowly progressive.\nSmoking\n~35 pack-years, still smokes.\nSputum\nSmall amount most mornings; no current fever.\nVariability\nSymptoms present most days rather than fully symptom-free between episodes.\nOrthopnoea/edema\nNo orthopnoea; no ankle swelling.\nManoeuvre / domain\nStandardized finding to provide\nVitals\nRR 20, SpO₂ 94% room air, HR 88.\nExpansion\nMildly reduced bilaterally.\nPercussion\nGenerally hyperresonant.\nAuscultation\nReduced air entry with prolonged expiration and scattered expiratory wheeze.\nCardiac/edema\nNo raised JVP; no edema.\nCode\nDomain\nScore\nH1\nCharacterises chronic dyspnea/cough/sputum and exacerbation pattern.\n0–2\nH2\nAssesses smoking/exposure history and considers asthma/cardiac/infective alternatives.\n0–2\nPE1\nVitals + RR/SpO₂/work of breathing.\n0–2\nPE2\nChest expansion/symmetry.\n0–2\nPE3\nComparative percussion.\n0–2\nPE4\nAuscultation of air entry and added sounds.\n0–2\nPE5\nFocused cardiovascular/edema screen when needed for alternatives.\n0–2\nPR\nProblem Representation\n0–2\nDDx\nRanked Differential Diagnosis\n0–2\nJUST\nEvidence justification\n0–2\nDomain\n0\n1\n2\nProblem Representation\nNo synthesis\nPartial\nOlder smoker with chronic progressive daily dyspnea/cough and obstructive examination pattern without focal infection/congestion.\nRanked Differential\nNo plausible\nCOPD named only\nCOPD leading; asthma/cardiac disease/other chronic lung disease ranked coherently.\nEvidence justification\nUnsupported\nOne clue\nExposure + persistent symptom pattern + obstructive PE findings, with lack of focal infection/volume overload.\nCritical safety / professionalism flags  Candidate station only. GOLD requires spirometry to establish COPD; the station must never score the physical examination as diagnostic proof.\n","anchor":"0 = omitted/unsafe/irrelevant; 1 = partially competent or poorly targeted; 2 = competent, targeted, and interpretable for this learner level.","global":"1 Unsafe/non-coherent; 2 Weak; 3 Developing; 4 Competent; 5 Strong. Report separately; never add to /20."}'::jsonb,'https://drive.google.com/file/d/1rPUKlJQ_cajr2av5r0IODik4zqOKeAXd/view' from public.programs where code='SEIP26' on conflict do nothing;
insert into public.fce_stations(program_id,code,version,title,core,candidate_instructions,examiner_package,source_url)
select id,'FCE-R2','1.0.0','Generalised edema with frothy urine',false,'In 8 minutes, take a focused History and perform a focused Physical Examination relevant to your working hypotheses. Explain what you are doing and respect consent. At the bell, move to the 4-minute post-encounter form: Problem Representation, ranked Differential Diagnosis and evidence justification.','{"domains":{"H1":"Clarifies edema distribution/tempo, frothy urine, urine volume and associated symptoms.","H2":"Assesses cardiac/liver alternatives and possible systemic/medication context.","PE1":"Vitals/BP and general appearance.","PE2":"Peripheral/periorbital edema assessment.","PE3":"JVP assessment.","PE4":"Lung bases for pulmonary congestion.","PE5":"Focused abdominal exam for ascites/hepatomegaly.","PR":"Problem Representation","DDx":"Ranked Differential Diagnosis","JUST":"Evidence justification"},"source_text":"RESERVE / PARALLEL CANDIDATE — NOT EQUIVALENCE-LOCKED  Renal. 12 minutes total: 8-minute observed encounter + 4-minute post-encounter reasoning.\nPrompt / domain\nSP response\nOpening\n“My feet are swollen and my urine looks very frothy.”\nCourse\nTwo weeks, both legs; face looks puffy in mornings.\nUrine\nFrothy; no dysuria; no visible blood.\nDyspnea\nNo orthopnoea or PND.\nLiver symptoms\nNo jaundice or abdominal swelling.\nMedication/context\nNo new NSAID course; no known heart/liver disease.\nManoeuvre / domain\nStandardized finding to provide\nVitals/BP\nBP 148/92, HR 82 regular.\nEdema\nBilateral pitting edema to mid-shin; mild periorbital puffiness.\nJVP\nNot elevated.\nLungs\nClear.\nAbdomen\nNo ascites; no hepatomegaly.\nCode\nDomain\nScore\nH1\nClarifies edema distribution/tempo, frothy urine, urine volume and associated symptoms.\n0–2\nH2\nAssesses cardiac/liver alternatives and possible systemic/medication context.\n0–2\nPE1\nVitals/BP and general appearance.\n0–2\nPE2\nPeripheral/periorbital edema assessment.\n0–2\nPE3\nJVP assessment.\n0–2\nPE4\nLung bases for pulmonary congestion.\n0–2\nPE5\nFocused abdominal exam for ascites/hepatomegaly.\n0–2\nPR\nProblem Representation\n0–2\nDDx\nRanked Differential Diagnosis\n0–2\nJUST\nEvidence justification\n0–2\nDomain\n0\n1\n2\nProblem Representation\nNo synthesis\nPartial\nAdult with acute/subacute bilateral edema, morning periorbital puffiness and frothy urine with hypertension, without congestion or liver findings.\nRanked Differential\nNo plausible\nRenal cause unranked\nGlomerular/nephrotic process leading; heart/liver causes ranked lower using JVP/lung/abdomen.\nEvidence justification\nUnsupported\nOne clue\nFrothy urine + edema + BP with absence of raised JVP/crackles/ascites support renal over cardiac/hepatic fluid retention.\nCritical safety / professionalism flags  Candidate only; nephrotic syndrome requires proteinuria/hypoalbuminemia evidence and should not be diagnosed from edema alone.","anchor":"0 = omitted/unsafe/irrelevant; 1 = partially competent or poorly targeted; 2 = competent, targeted, and interpretable for this learner level.","global":"1 Unsafe/non-coherent; 2 Weak; 3 Developing; 4 Competent; 5 Strong. Report separately; never add to /20."}'::jsonb,'https://drive.google.com/file/d/1rPUKlJQ_cajr2av5r0IODik4zqOKeAXd/view' from public.programs where code='SEIP26' on conflict do nothing;
